<?php $pages=$result['pages']??max(1,(int)ceil($result['count']/$result['per']));$current=$result['page']; ?>
<div class="admin-pagination"><p><?= fa($result['count']) ?> رکورد · صفحه <?= fa($current) ?> از <?= fa($pages) ?></p><?php if($pages>1): ?><nav aria-label="صفحه‌بندی"><a class="outline" href="<?= e(url('admin',['p'=>1]+array_diff_key($f,['page'=>true,'p'=>true]))) ?>">ابتدا</a><?php for($n=max(1,$current-2);$n<=min($pages,$current+2);$n++): ?><a class="pill <?= $n===$current?'active':'' ?>" href="<?= e(url('admin',['p'=>$n]+array_diff_key($f,['page'=>true,'p'=>true]))) ?>" <?= $n===$current?'aria-current="page"':'' ?>><?= fa($n) ?></a><?php endfor ?><a class="outline" href="<?= e(url('admin',['p'=>$pages]+array_diff_key($f,['page'=>true,'p'=>true]))) ?>">آخر</a></nav><?php endif ?></div>
